using System.ComponentModel;
using System.Text.Json;
using System.Text.Json.Nodes;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;
namespace PowerShapeMcp;
[McpServerToolType]
public sealed class OwnedCurveTranslationTools(BridgeSession session){
 [McpServerTool(Name="execute_owned_curve_translation",ReadOnly=false,Destructive=true,Idempotent=false,OpenWorld=false)]
 [Description("Translate one explicit COMPCURVE among one unchanged SOLID in an owned WORLD/mm/idle/empty-selection copy. Reuses the original disabled translate_entities/ownedOperationHandle and shared one-call TranslateItem claim/fence/journal lifecycle. curveRange must cover independently read POINT.NUMBER,1..N (2..32). Checks actual2D control positions, tangents/magnitudes/free flags and SOLID face witnesses. Fenced until independent verifier. No selection/save/OPEN/close/inverse/replay. Full only, separately default-off; not full topology.")]
 public Task<CallToolResult> Execute([Description("Unconsumed prepared ownedOperationHandle for the exact one-curve set/vector in this connection.")]string ownedOperationHandle,[Description("Exact startIndex=1,endIndex=N, N2..32; known complete curve controls, not inferred domain.")]JsonElement curveRange,CancellationToken cancellationToken)=>new ExecutionTools(session).Run("execute_owned_curve_translation",new(){["ownedOperationHandle"]=ownedOperationHandle,["curveRange"]=JsonNode.Parse(curveRange.GetRawText())},cancellationToken);
 [McpServerTool(Name="verify_owned_curve_translation",ReadOnly=false,Destructive=false,Idempotent=false,OpenWorld=false)]
 [Description("Independently verify original one-COMPCURVE translation using its raw receipt/claim/journal, fresh candidate/listing, fresh full curve controls and unchanged SOLID face witnesses. May complete original journal and release only its matching fence. No CAD command, replay, save or topology certificate. Full only.")]
 public Task<CallToolResult> Verify([Description("Original native execution requestID.")]string executionRequestId,[Description("Original immutable native execution SHA256.")]string executionReceiptSha256,[Description("Fresh candidate document read after command return.")]string candidateDocumentHandle,[Description("Fresh one-use active document choice.")]string activeDocumentHandle,CancellationToken cancellationToken)=>new ExecutionTools(session).Run("verify_owned_curve_translation",new(){["executionRequestId"]=executionRequestId,["executionReceiptSha256"]=executionReceiptSha256,["candidateDocumentHandle"]=candidateDocumentHandle,["activeDocumentHandle"]=activeDocumentHandle},cancellationToken);
 public static McpServerTool[] Create(BridgeSession s){if(!s.ExecutionEnabled("execute_owned_curve_translation"))return[];var t=new OwnedCurveTranslationTools(s);var schema=SolidQuarterTurnTools.Schema("ownedOperationHandle");schema["properties"]!["curveRange"]=new JsonObject{["type"]="object",["properties"]=new JsonObject{["startIndex"]=new JsonObject{["type"]="integer",["const"]=1},["endIndex"]=new JsonObject{["type"]="integer",["minimum"]=2,["maximum"]=32}},["required"]=new JsonArray("startIndex","endIndex"),["additionalProperties"]=false};schema["required"]!.AsArray().Add("curveRange");return[new StrictTool(McpServerTool.Create(t.Execute),s,schema,x=>CurveTranslationProof.Range(x["curveRange"]!.AsObject())),new StrictTool(McpServerTool.Create(t.Verify),s,SolidQuarterTurnTools.Schema("executionRequestId","executionReceiptSha256","candidateDocumentHandle","activeDocumentHandle"))];}
}
